# -*- coding: utf-8 -*-
"""
Authentic TOEIC Part 3 (16 Conversations = 48 Qs) & Part 4 (16 Short Talks = 48 Qs) bank
spanning ETS 2024/2025/2026 Tests (6 P3 + 6 P4 = 36 Qs) and 10 Drills (10 P3 + 10 P4 = 60 Qs).
Every set has multi-speaker US/UK/AU voices, evidence anchors, paraphrase tables, trap analyses,
and saveable Key Vocab items.
"""
from typing import Any, Dict, List, Optional, Tuple
from . import (
    VOICES_AU_F,
    VOICES_AU_M,
    VOICES_UK_F,
    VOICES_UK_M,
    VOICES_US_F,
    VOICES_US_M,
)


def _line(
    lid: str,
    speaker: str,
    gender: str,
    accent: str,
    voice: str,
    en: str,
    vi: str,
    ev_qids: Optional[List[str]] = None,
) -> Dict[str, Any]:
    return {
        "id": lid,
        "speaker": speaker,
        "voiceGender": gender,
        "accent": accent,
        "voice": voice,
        "en": en,
        "vi": vi,
        "evidenceForQuestionIds": ev_qids or [],
    }


def _subq(
    qid: str,
    qnum: int,
    qtype: str,
    prompt: str,
    prompt_vi: str,
    opts: Dict[str, Tuple[str, str]],
    ans: str,
    trap_type: str,
    trap_analysis: str,
    opt_analysis: Dict[str, str],
    paraphrases: List[Tuple[str, str, str]],
) -> Dict[str, Any]:
    return {
        "id": qid,
        "questionNumber": qnum,
        "questionType": qtype,
        "prompt": prompt,
        "promptVi": prompt_vi,
        "options": {k: {"en": opts[k][0], "vi": opts[k][1]} for k in ["A", "B", "C", "D"]},
        "correctAnswer": ans,
        "explanation": {
            "trapType": trap_type,
            "trapAnalysis": trap_analysis,
            "paraphrases": [
                {"audioPhrase": a, "answerPhrase": b, "meaningVi": c}
                for (a, b, c) in paraphrases
            ],
            "optionAnalysis": opt_analysis,
            "keyVocab": [],
        },
    }


def _vocab(
    vid: str, word: str, pos: str, uk: str, us: str, vi: str, ex_en: str, ex_vi: str
) -> Dict[str, Any]:
    return {
        "id": vid,
        "word": word,
        "pos": pos,
        "ipaUK": uk,
        "ipaUS": us,
        "meaning": vi,
        "exampleEn": ex_en,
        "exampleVi": ex_vi,
    }


def _build_p3(
    sid: str,
    title: str,
    scenario: str,
    speakers: int,
    lines: List[Dict[str, Any]],
    qs: List[Dict[str, Any]],
    vocab: List[Dict[str, Any]],
    graphic: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    d: Dict[str, Any] = {
        "id": sid,
        "part": 3,
        "title": title,
        "scenario": scenario,
        "speakerCount": speakers,
        "hasGraphic": bool(graphic),
        "audioFile": f"{sid}.mp3",
        "transcript": lines,
        "questions": qs,
        "keyVocab": vocab,
    }
    if graphic:
        d["graphic"] = graphic
    return d


def _build_p4(
    sid: str,
    title: str,
    talk_type: str,
    lines: List[Dict[str, Any]],
    qs: List[Dict[str, Any]],
    vocab: List[Dict[str, Any]],
    graphic: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    d: Dict[str, Any] = {
        "id": sid,
        "part": 4,
        "title": title,
        "talkType": talk_type,
        "hasGraphic": bool(graphic),
        "audioFile": f"{sid}.mp3",
        "transcript": lines,
        "questions": qs,
        "keyVocab": vocab,
    }
    if graphic:
        d["graphic"] = graphic
    return d


